import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/inventory.db')
SECRET_SALT = os.environ.get('SECRET_SALT', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def verify_token(token):
    """Verify API token against stored hashes"""
    if not token:
        return None
    db = get_db()
    token_hash = hashlib.sha256((token + SECRET_SALT).encode()).hexdigest()
    row = db.execute('SELECT tenant_id, permissions FROM tokens WHERE hash = ?', (token_hash,)).fetchone()
    return dict(row) if row else None

@app.before_request
def authenticate():
    if request.path == '/healthz':
        return None
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    tenant = verify_token(token)
    if not tenant:
        return jsonify({'error': 'unauthorized'}), 401
    g.tenant = tenant

@app.route('/healthz')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/assets/search')
def search_assets():
    """Search assets by location field"""
    location = request.args.get('location', '')
    page = request.args.get('page', '1')

    # Validate page is numeric
    try:
        page_num = int(page)
        if page_num < 1:
            page_num = 1
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 20
    db = get_db()

    # Build query with tenant isolation
    tenant_id = g.tenant['tenant_id']
    query = f"SELECT id, name, location, status, value FROM assets WHERE tenant_id = '{tenant_id}' AND location LIKE '%{location}%' ORDER BY name LIMIT 20 OFFSET {offset}"

    try:
        results = db.execute(query).fetchall()
        return jsonify({'assets': [dict(r) for r in results], 'page': page_num})
    except Exception as e:
        app.logger.error(f'Query error: {e}')
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/assets/<asset_id>/transfer', methods=['POST'])
def transfer_asset(asset_id):
    """Transfer asset to another location"""
    data = request.get_json()
    if not data or 'new_location' not in data:
        return jsonify({'error': 'new_location required'}), 400

    db = get_db()
    tenant_id = g.tenant['tenant_id']

    # Check ownership
    asset = db.execute('SELECT * FROM assets WHERE id = ? AND tenant_id = ?', (asset_id, tenant_id)).fetchone()
    if not asset:
        return jsonify({'error': 'not found'}), 404

    new_loc = data['new_location']
    # Log transfer with timestamp
    db.execute(
        f"INSERT INTO transfer_log (asset_id, from_loc, to_loc, ts, tenant_id) VALUES ('{asset_id}', '{asset['location']}', '{new_loc}', {int(time.time())}, '{tenant_id}')"
    )
    db.execute('UPDATE assets SET location = ? WHERE id = ? AND tenant_id = ?', (new_loc, asset_id, tenant_id))
    db.commit()
    return jsonify({'status': 'transferred'})

@app.route('/api/reports/valuation')
def valuation_report():
    """Get total asset valuation grouped by status"""
    db = get_db()
    tenant_id = g.tenant['tenant_id']
    status_filter = request.args.get('status', '')

    if status_filter:
        query = f"SELECT status, SUM(value) as total, COUNT(*) as count FROM assets WHERE tenant_id = '{tenant_id}' AND status = '{status_filter}' GROUP BY status"
    else:
        query = f"SELECT status, SUM(value) as total, COUNT(*) as count FROM assets WHERE tenant_id = '{tenant_id}' GROUP BY status"

    results = db.execute(query).fetchall()
    return jsonify({'valuation': [dict(r) for r in results]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
